PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?shortfall)) AS ?total_goal_shortfall)
    WHERE {
      ?goal a wm:InvestmentGoal .
      ?goal wm:shortfall ?shortfall .
      ?goal wm:belongsToInvestor ?inv .
      ?inv wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?total_holding_gain)
    WHERE {
      ?holding a wm:PortfolioHolding .
      ?holding wm:currentValue ?cv .
      ?holding wm:cost ?c .
      BIND(xsd:decimal(?cv) - xsd:decimal(?c) AS ?gain) .
      ?holding wm:heldByInvestor ?inv .
      ?inv wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?total_cash_flow)
    WHERE {
      ?cf a wm:CashFlow .
      ?cf wm:amount ?amount .
      ?cf wm:cashFlowOfInvestor ?inv .
      ?inv wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor .
  ?investor wm:investorId ?investorId .
  ?investor wm:investorName ?investorName .
  FILTER(?total_goal_shortfall > 0 && ?total_holding_gain < 0 && ?total_cash_flow < 10000)
}

