SELECT ?investorId ?investorName ?riskScore ?shortfall ?negativeHoldingCount
WHERE {
  ?investor a wm:Investor ;
            wm:segment ?segment ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasPortfolioHealth ?health .
  FILTER(LCASE(STR(?segment)) = "aggressive") .

  ?goal wm:shortfall ?shortfallRaw .
  BIND(xsd:decimal(?shortfallRaw) AS ?shortfall) .
  FILTER(?shortfall > 0) .

  ?health wm:riskScore ?riskScoreRaw .
  BIND(xsd:decimal(?riskScoreRaw) AS ?riskScore) .
  FILTER(?riskScore > 65) .

  {
    SELECT ?investorId (COUNT(?holding) AS ?negativeHoldingCount)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?inv ;
               wm:returnsPct ?returnsRaw .
      FILTER(xsd:decimal(?returnsRaw) < 0) .
      ?inv wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
}

