SELECT ?investorName ?investorId ?combinedValue
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:hasPortfolioHealth ?ph .
  ?ph wm:riskScore ?riskScore .
  FILTER (xsd:decimal(?riskScore) > 60)

  {
    SELECT ?investorId (SUM(xsd:decimal(?currVal)) AS ?totalHolding)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?invH ;
               wm:currentValue ?currVal .
      ?invH wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?shortfall)) AS ?totalShortfall)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?invG ;
            wm:shortfall ?shortfall .
      ?invG wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  BIND ( (xsd:decimal(?totalHolding) + xsd:decimal(?totalShortfall)) AS ?combinedValue )
}
ORDER BY DESC(?combinedValue)
LIMIT 5

