PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:riskTolerance "Aggressive" .

  FILTER EXISTS {
    ?investor wm:hasInvestmentGoal ?goal .
    ?goal wm:shortfall ?shortfall .
    FILTER(xsd:decimal(?shortfall) > 0)
  }

  FILTER EXISTS {
    ?investor wm:hasHolding ?holding .
    ?holding wm:investmentName "Gold" .
  }

  FILTER EXISTS {
    ?ph rdf:type wm:PortfolioHealth ;
        wm:healthOfInvestor ?investor ;
        wm:riskScore ?riskScore .
    FILTER(xsd:decimal(?riskScore) > 60)
  }

  FILTER EXISTS {
    ?alloc rdf:type wm:SectorAllocation ;
           wm:allocationOfInvestor ?investor ;
           wm:allocationPct ?allocPct .
    FILTER(xsd:decimal(?allocPct) > 30)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  {
    SELECT ?investorId (MAX(xsd:decimal(?shortfall)) AS ?shortfall_max)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:shortfall ?shortfall ;
            wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  FILTER(?shortfall_max > 0)

  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?holding_gain_sum)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:currentValue ?cv ;
               wm:cost ?c ;
               wm:investorId ?investorId .
      BIND(xsd:decimal(?cv) - xsd:decimal(?c) AS ?gain)
    }
    GROUP BY ?investorId
  }
  FILTER(?holding_gain_sum < 0)

  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cash_flow_sum)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:amount ?amount ;
          wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  FILTER(?cash_flow_sum < 10000)

  {
    SELECT ?investorId (MAX(xsd:decimal(?rs)) AS ?riskScore)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:riskScore ?rs ;
          wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  FILTER(?riskScore > 65)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:investorId ?investorIdRaw . }
  BIND(COALESCE(STR(?investorIdRaw), "NULL") AS ?investorId)
  OPTIONAL { ?investor wm:investorName ?investorNameRaw . }
  BIND(COALESCE(STR(?investorNameRaw), "NULL") AS ?investorName)
  OPTIONAL { ?investor wm:riskTolerance ?riskTol . }
  OPTIONAL { ?investor wm:category ?cat . }
  FILTER ( (!BOUND(?riskTol) || STRLEN(STR(?riskTol)) = 0) && (!BOUND(?cat) || STRLEN(STR(?cat)) = 0) )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?goal_count WHERE {
  {
    SELECT ?investorId (COUNT(?goalId) AS ?goal_count) WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:goalId ?goalId .
      ?inv wm:investorId ?investorId .
    }
    GROUP BY ?investorId
    HAVING (COUNT(?goalId) >= 4)
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:timeHorizon ?timeHorizon .
  FILTER(LCASE(STR(?timeHorizon)) = "long-term")
  OPTIONAL { ?investor wm:investorName ?investorName . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?goal_count (COUNT(?investorId) AS ?investor_count)
WHERE {
  {
    SELECT ?investorId ?riskTolerance (COUNT(?goal) AS ?goalCount)
    WHERE {
      ?investor a wm:Investor .
      ?investor wm:investorId ?investorId .
      OPTIONAL { ?investor wm:riskTolerance ?rt . }
      BIND(COALESCE(?rt, "NULL") AS ?riskTolerance)
      ?investor wm:hasInvestmentGoal ?goal .
      ?goal a wm:InvestmentGoal .
    }
    GROUP BY ?investorId ?riskTolerance
  }
  BIND(
    IF(?goalCount = 1, "1",
      IF(?goalCount = 2, "2",
        IF(?goalCount = 3, "3", "4+")
      )
    ) AS ?goal_count
  )
}
GROUP BY ?riskTolerance ?goal_count
ORDER BY ?riskTolerance ?goal_count

