SELECT ?investor_category (COUNT(?holdingId) AS ?number_of_holdings) (COUNT(DISTINCT ?investorId) AS ?number_of_distinct_investors)
WHERE {
  ?holding a wm:PortfolioHolding ;
           wm:holdingId ?holdingId ;
           wm:heldByInvestor ?investor .
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  OPTIONAL { ?investor wm:category ?catRaw . }
  BIND(COALESCE(STR(?catRaw), "NULL") AS ?investor_category)
}
GROUP BY ?investor_category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?underfundedGoalCount WHERE {
  {
    SELECT ?investorId (COUNT(?goal) AS ?underfundedGoalCount) WHERE {
      ?goal a wm:InvestmentGoal .
      ?goal wm:shortfall ?shortfall .
      FILTER(xsd:decimal(?shortfall) > 0) .
      ?goal wm:belongsToInvestor ?inv .
      ?inv wm:investorId ?investorId .
    }
    GROUP BY ?investorId
    HAVING (COUNT(?goal) >= 3)
  }
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?avgProgress ?riskScore
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:hasPortfolioHealth ?ph ;
       wm:riskTolerance ?riskTol .
  OPTIONAL { ?inv wm:investorName ?investorName . }
  FILTER(LCASE(STR(?riskTol)) = "moderate")
  ?ph wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 60)

  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avgProgress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
  }
  FILTER(xsd:decimal(?avgProgress) < 30)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorName ?investorName ;
            wm:investorId ?invId .
  ?rebalance a wm:ScenarioRebalancing ;
             wm:investorId ?invId ;
             wm:scenario ?scenario ;
             wm:hasMarketScenario ?market .
  FILTER(LCASE(STR(?scenario)) = "tactical") .
  ?market rdfs:label ?marketLabel .
  FILTER(CONTAINS(LCASE(STR(?marketLabel)), "bear")) .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sector (COALESCE(?holdingSum, 0) AS ?total_holding_value) (COALESCE(?allocationSum, 0) AS ?total_sector_allocation_investment)
WHERE {
  ?sectorIRI a wm:Sector ;
             rdfs:label ?sector .

  OPTIONAL {
    SELECT ?sectorIRI (SUM(xsd:decimal(?cv)) AS ?holdingSum)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:hasSector ?sectorIRI ;
               wm:currentValue ?cv .
    }
    GROUP BY ?sectorIRI
  }

  OPTIONAL {
    SELECT ?sectorIRI (SUM(xsd:decimal(?ti)) AS ?allocationSum)
    WHERE {
      ?alloc a wm:SectorAllocation ;
            wm:hasSector ?sectorIRI ;
            wm:totalInvestment ?ti .
    }
    GROUP BY ?sectorIRI
  }
}
ORDER BY ?sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
