SELECT ?investorId ?investorName (COUNT(?cashFlowId) AS ?cashFlowCount)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .

  ?cashFlow a wm:CashFlow ;
            wm:cashFlowId ?cashFlowId ;
            wm:date ?cfDate ;
            wm:cashFlowOfInvestor ?investor .
  FILTER(CONTAINS(LCASE(STR(?cfDate)), "2025"))

  FILTER NOT EXISTS {
    ?holding a wm:PortfolioHolding ;
             wm:purchaseDate ?holdDate ;
             wm:heldByInvestor ?investor .
    FILTER(CONTAINS(LCASE(STR(?holdDate)), "2025"))
  }
}
GROUP BY ?investorId ?investorName

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName WHERE {
  {
    SELECT DISTINCT ?investor WHERE {
      ?investor a wm:Investor .
      ?investor wm:hasPortfolioHealth ?ph .
      ?ph wm:riskScore ?riskScore ;
          wm:diversificationScore ?divScore .
      FILTER(xsd:decimal(?riskScore) > 70 && xsd:decimal(?divScore) < 30) .
      ?investor wm:hasSectorAllocation ?sa .
      ?sa wm:allocationPct ?allocPct .
      FILTER(xsd:decimal(?allocPct) > 40) .
    }
  }
  ?investor wm:investorId ?investorId ;
            wm:investorName ?investorName .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_band 
       (SUM(xsd:decimal(?holdingValue)) AS ?total_holding_value) 
       (SUM(xsd:decimal(?sectorInvest)) AS ?total_sector_allocation_investment)
WHERE {
  {
    SELECT ?investorId ?segment (SUM(xsd:decimal(?currentValue)) AS ?holdingValue)
    WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:investorId ?investorId ;
          wm:currentValue ?currentValue .
      OPTIONAL { ?ph wm:segment ?segment . }
    }
    GROUP BY ?investorId ?segment
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?totalInvestment)) AS ?sectorInvest)
    WHERE {
      ?sa a wm:SectorAllocation ;
          wm:investorId ?investorId ;
          wm:totalInvestment ?totalInvestment .
    }
    GROUP BY ?investorId
  }
  BIND(COALESCE(STR(?segment), "NULL") AS ?risk_band)
}
GROUP BY ?risk_band

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasHolding ?holding ;
            wm:hasCashFlow ?cashFlow ;
            wm:hasRebalancingAction ?reb .

  ?holding a wm:PortfolioHolding .
  ?cashFlow a wm:CashFlow ;
            wm:date ?cfDate .
  FILTER(CONTAINS(LCASE(STR(?cfDate)), "2025"))
  ?reb a wm:RebalancingAction .
}
GROUP BY ?investorId ?investorName

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?inv ?investorId ?investorName ?avg_progress ?riskScore ?allocationPct
WHERE {
  # Investor entity
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  # PortfolioHealth linked to investor
  ?ph a wm:PortfolioHealth ;
      wm:healthOfInvestor ?inv ;
      wm:riskScore ?riskScoreRaw .
  BIND(xsd:decimal(?riskScoreRaw) AS ?riskScore)
  FILTER(?riskScore > 60)

  # Average InvestmentGoal progress per investor (must be <30)
  {
    SELECT ?investorId (AVG(xsd:decimal(?progress)) AS ?avg_progress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:progressPct ?progress .
    }
    GROUP BY ?investorId
    HAVING (AVG(xsd:decimal(?progress)) < 30)
  }

  # Maximum SectorAllocation per investor (must be >30)
  {
    SELECT ?investorId (MAX(xsd:decimal(?alloc)) AS ?allocationPct)
    WHERE {
      ?allocRec a wm:SectorAllocation ;
                wm:investorId ?investorId ;
                wm:allocationPct ?alloc .
    }
    GROUP BY ?investorId
    HAVING (MAX(xsd:decimal(?alloc)) > 30)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  {
    SELECT ?inv (AVG(xsd:decimal(?progressPct)) AS ?avg_progress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:progressPct ?progressPct ;
            wm:belongsToInvestor ?inv .
    }
    GROUP BY ?inv
  }

  {
    SELECT ?inv (AVG(xsd:decimal(?riskScore)) AS ?risk_score)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:riskScore ?riskScore ;
          wm:healthOfInvestor ?inv .
    }
    GROUP BY ?inv
  }

  {
    SELECT ?inv (SUM(?withdrawalAmt) AS ?sum_withdrawal) (SUM(?depositAmt) AS ?sum_deposit)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:amount ?amt ;
          wm:type ?type ;
          wm:cashFlowOfInvestor ?inv .
      BIND(IF(LCASE(STR(?type)) = "withdrawal", xsd:decimal(?amt), 0) AS ?withdrawalAmt)
      BIND(IF(LCASE(STR(?type)) = "deposit", xsd:decimal(?amt), 0) AS ?depositAmt)
    }
    GROUP BY ?inv
  }

  {
    SELECT ?inv (COUNT(?ra) AS ?count_sell)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:action ?action ;
          wm:rebalancingActionOfInvestor ?inv .
      FILTER(LCASE(STR(?action)) = "sell")
    }
    GROUP BY ?inv
  }

  BIND((?sum_withdrawal - ?sum_deposit) AS ?diff_withdrawal_deposit)

  FILTER(?avg_progress < 30 && ?risk_score > 60 && ?diff_withdrawal_deposit > 0 && ?count_sell >= 1)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
