SELECT DISTINCT ?goal_context_value
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:riskTolerance ?riskTol ;
            wm:investorId ?invId .
  FILTER(LCASE(STR(?riskTol)) = "aggressive")
  ?goal rdf:type wm:InvestmentGoal ;
        wm:investorId ?invId ;
        wm:investmentGoal ?goal_context_value .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
