PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName (COUNT(?holdingId) AS ?holding_count)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:category ?cat ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasHolding ?holding .

  FILTER(LCASE(?cat) = "equity")

  ?goal a wm:InvestmentGoal ;
        wm:investmentGoal ?goalName .
  FILTER(LCASE(?goalName) = "retirement planning")

  ?holding a wm:PortfolioHolding ;
           wm:investmentType ?invType ;
           wm:holdingId ?holdingId .
  FILTER(LCASE(?invType) = "government bond")
}
GROUP BY ?investorId ?investorName
HAVING (COUNT(?holdingId) > 0)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?investmentType (COUNT(DISTINCT ?investorId) AS ?distinct_investor_count)
WHERE {
  {
    SELECT DISTINCT ?investorId ?riskTolerance ?investmentType
    WHERE {
      ?holding wm:heldByInvestor ?investor ;
               wm:hasInvestmentType ?invType .

      OPTIONAL { ?holding wm:investorId ?hid . }
      OPTIONAL { ?investor wm:investorId ?iid . }
      BIND( COALESCE(?hid, ?iid) AS ?investorId )

      OPTIONAL { ?investor wm:riskTolerance ?rt . }
      BIND( COALESCE(STR(?rt), "NULL") AS ?riskTolerance )

      OPTIONAL { ?invType rdfs:label ?invLabel . }
      BIND( COALESCE(STR(?invLabel), "NULL") AS ?investmentType )
    }
  }
}
GROUP BY ?riskTolerance ?investmentType

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:hasHolding ?holding ;
       wm:hasSectorAllocation ?allocation .

  ?holding wm:sector ?holdingSector .
  FILTER(LCASE(?holdingSector) = "real estate")

  ?allocation wm:sector ?allocationSector .
  FILTER(LCASE(?allocationSector) = "real estate")
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sector (AVG(?invDivScore) AS ?avg_diversification_score)
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?divScore)) AS ?invDivScore)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:investorId ?investorId ;
          wm:diversificationScore ?divScore .
    }
    GROUP BY ?investorId
  }
  ?phold a wm:PortfolioHolding ;
          wm:investorId ?investorId .
  OPTIONAL {
    ?phold wm:hasSector ?sectorIRI .
    OPTIONAL { ?sectorIRI rdfs:label ?sectorLabel . }
  }
  BIND(COALESCE(?sectorLabel, "NULL") AS ?sector)
}
GROUP BY ?sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?goal_context (AVG(xsd:decimal(?shortfall)) AS ?avg_shortfall)
WHERE {
  ?goal a wm:InvestmentGoal ;
        wm:shortfall ?shortfall ;
        wm:belongsToInvestor ?inv .
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:category ?catRaw . }
  BIND(COALESCE(STR(?catRaw), "NULL") AS ?category) .
  OPTIONAL { ?goal wm:investmentGoal ?goalCtxRaw . }
  BIND(COALESCE(STR(?goalCtxRaw), "NULL") AS ?goal_context) .
}
GROUP BY ?category ?goal_context

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?goal_context (AVG(xsd:decimal(?progressPct)) AS ?average_progress)
WHERE {
  ?inv rdf:type wm:Investor ;
       wm:riskTolerance ?risk ;
       wm:investorId ?invId .
  FILTER(LCASE(STR(?risk)) = "aggressive") .

  ?goal rdf:type wm:InvestmentGoal ;
        wm:belongsToInvestor ?inv ;
        wm:investmentGoal ?goal_context ;
        wm:progressPct ?progressPct .
}
GROUP BY ?goal_context
ORDER BY DESC(?average_progress) ?goal_context
LIMIT 5
